// Shared social image (generated by app/opengraph-image.js). Page-level
// `openGraph` replaces the root one, so it has to be repeated here.
const ogImage = { url: "/opengraph-image", width: 1200, height: 630, alt: "Growthys — Digital Growth Agency" };

// Per-page metadata with canonical URL and matching Open Graph/Twitter tags.
export function pageMeta({ title, description, path, type = "website", ...rest }) {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title: `${title} | Growthys`, description, url: path, type, siteName: "Growthys", images: [ogImage] },
    twitter: { card: "summary_large_image", title: `${title} | Growthys`, description, images: [ogImage.url] },
    ...rest,
  };
}
